"""Minimal, privacy-conscious client for OpenAI's Responses API.

This module uses only Python's standard library. It does not log prompts or
responses and asks the Responses API not to store the request (``store=False``).
"""

from __future__ import annotations

import json
import os
import ssl
import urllib.error
import urllib.request
from typing import Any, Mapping


_RESPONSES_URL = "https://api.openai.com/v1/responses"


class OpenAIError(RuntimeError):
    """Raised when the Responses API request fails."""


def send_prompt(
    prompt: str,
    *,
    model: str,
    api_key: str | None = None,
    timeout: float = 60.0,
) -> dict[str, Any]:
    """Send a private text prompt and return the decoded API response.

    ``api_key`` defaults to the ``OPENAI_API_KEY`` environment variable.
    ``model`` is required so callers explicitly choose a model available to
    their OpenAI project.
    """
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be positive")

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError(
            "No API key supplied; pass api_key or set OPENAI_API_KEY"
        )

    body = json.dumps(
        {"model": model, "input": prompt, "store": False},
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    request = urllib.request.Request(
        _RESPONSES_URL,
        data=body,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "stdlib-openai-responses-client/1.0",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(
            request, timeout=timeout, context=ssl.create_default_context()
        ) as response:
            result = json.load(response)
    except urllib.error.HTTPError as exc:
        request_id = exc.headers.get("x-request-id")
        detail = f"OpenAI API returned HTTP {exc.code}"
        if request_id:
            detail += f" (request ID: {request_id})"
        raise OpenAIError(detail) from exc
    except (urllib.error.URLError, TimeoutError) as exc:
        raise OpenAIError("Could not reach the OpenAI API") from exc
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise OpenAIError("OpenAI API returned an invalid JSON response") from exc

    if not isinstance(result, dict):
        raise OpenAIError("OpenAI API returned an unexpected response")
    return result


def output_text(response: Mapping[str, Any]) -> str:
    """Extract and concatenate text output from a Responses API response."""
    parts: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, Mapping) or item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if isinstance(content, Mapping) and content.get("type") == "output_text":
                text = content.get("text")
                if isinstance(text, str):
                    parts.append(text)
    return "".join(parts)
